    t96 = _depthwise_conv2d(t95, c61, c24, stride=(1, 1), dilation=(1, 1), padding='SAME', act='RELU6')
    t97 = _conv2d(t96, c41, c62, stride=(1, 1), dilation=(1, 1), padding='SAME', act='NONE')
    t98 = _act(jnp.add(t94, t97), 'RELU6')
    t99 = _conv2d(t98, c42, c8, stride=(1, 1), dilation=(1, 1), padding='SAME', act='RELU6')
    t100 = _depthwise_conv2d(t99, c63, c25, stride=(2, 2), dilation=(1, 1), padding='SAME', act='RELU6')
    t101 = _conv2d(t100, c43, c9, stride=(1, 1), dilation=(1, 1), padding='SAME', act='RELU6')
    t102 = _conv2d(t101, c44, c10, stride=(1, 1), dilation=(1, 1), padding='SAME', act='RELU6')
    t103 = _depthwise_conv2d(t102, c64, c26, stride=(1, 1), dilation=(1, 1), padding='SAME', act='RELU6')
    t104 = _conv2d(t103, c45, c65, stride=(1, 1), dilation=(1, 1), padding='SAME', act='NONE')
    t105 = _act(jnp.add(t101, t104), 'RELU6')
    t106 = _conv2d(t105, c46, c11, stride=(1, 1), dilation=(1, 1), padding='SAME', act='RELU6')
    t107 = _depthwise_conv2d(t106, c66, c27, stride=(1, 1), dilation=(1, 1), padding='SAME', act='RELU6')
    t108 = _conv2d(t107, c47, c67, stride=(1, 1), dilation=(1, 1), padding='SAME', act='NONE')
    t109 = _act(jnp.add(t105, t108), 'RELU6')
    t110 = _conv2d(t109, c48, c1, stride=(1, 1), dilation=(1, 1), padding='SAME', act='RELU')
    t111 = _pool(t110, 'AVG', window=(4, 4), stride=(1, 1), padding='VALID', act='NONE')
    t112 = _conv2d(t111, c49, c2, stride=(1, 1), dilation=(1, 1), padding='SAME', act='RELU')
    t113 = _conv2d(t112, c50, c68, stride=(1, 1), dilation=(1, 1), padding='SAME', act='NONE')
    t114 = jnp.reshape(t113, (1, 154))

    return t114
